option.value:
@import 'tailwindcss';
@plugin '@tailwindcss/forms';
@plugin '@tailwindcss/typography';

@font-face {
	font-family: 'Lato';
	font-style: normal;
	font-weight: 300;
	font-display: swap;
	src: url('/theme/assets/fonts/Lato/Lato-Light.woff2') format('woff2');
}

@font-face {
	font-family: 'Lato';
	font-style: normal;
	font-weight: 400;
	font-display: swap;
	src: url('/theme/assets/fonts/Lato/Lato-Regular.woff2') format('woff2');
}

@font-face {
	font-family: 'Lato';
	font-style: normal;
	font-weight: 700;
	font-display: swap;
	src: url('/theme/assets/fonts/Lato/Lato-Bold.woff2') format('woff2');
}

@font-face {
	font-family: 'Lato';
	font-style: normal;
	font-weight: 900;
	font-display: swap;
	src: url('/theme/assets/fonts/Lato/Lato-Black.woff2') format('woff2');
}

:root {
	--ink: #960B0A;
	--ink-deep: #5a0707;
	--blue: #960b0a;
	--blue-soft: #b91818;
	--aqua: #fb8352;
	--aqua-strong: #ff9f73;
	--orange: #fb8352;
	--gold: #f7b23a;
	--paper: #fbfaf7;
	--muted: #68707c;
	--line: rgb(255 255 255 / 16%);
	--shadow-soft: 0 26px 80px rgb(0 0 0 / 28%);
	--shadow-card: 0 18px 52px rgb(0 0 0 / 18%);
}

* {
	box-sizing: border-box;
}

html {
	scroll-behavior: smooth;
}

body {
	margin: 0;
	background: var(--ink);
	color: #0b0d17;
	font-family: 'Lato', Arial, sans-serif;
	-webkit-font-smoothing: antialiased;
	text-rendering: geometricPrecision;
}

img {
	display: block;
	max-width: 100%;
}

a {
	color: inherit;
	text-decoration: none;
}

button {
	border: 0;
	font: inherit;
}

.site-shell {
	width: min(100%, 1720px);
	margin: 0 auto;
	overflow: hidden;
	background: var(--paper);
	box-shadow: 0 0 0 1px rgb(4 13 71 / 8%);
}

.hero-section {
	--hero-gutter: clamp(24px, 7vw, 160px);
	position: relative;
	isolation: isolate;
	overflow: hidden;
	padding: 42px var(--hero-gutter) 64px;
	color: #131313;
	background:
		repeating-linear-gradient(
			90deg,
			rgb(251 131 82 / 12%) 0,
			rgb(251 131 82 / 12%) 1px,
			transparent 1px,
			transparent 68px
		),
		repeating-linear-gradient(
			0deg,
			rgb(251 131 82 / 12%) 0,
			rgb(251 131 82 / 12%) 1px,
			transparent 1px,
			transparent 68px
		),
		radial-gradient(circle at 22% 16%, rgb(251 131 82 / 11%), transparent 26rem),
		radial-gradient(circle at 78% 36%, rgb(150 11 10 / 9%), transparent 30rem),
		linear-gradient(180deg, #fff 0%, #fff 100%);
}

.ambient,
.shape {
	pointer-events: none;
	position: absolute;
	z-index: -1;
}

.ambient {
	width: 34rem;
	height: 34rem;
	border: 1px solid rgb(251 131 82 / 8%);
	border-radius: 999px;
	background: radial-gradient(circle, rgb(251 131 82 / 8%), transparent 66%);
	filter: blur(4px);
	animation: float-slow 13s ease-in-out infinite;
}

.ambient-one {
	top: 7rem;
	left: -18rem;
}

.ambient-two {
	right: -16rem;
	bottom: 42rem;
	animation-delay: -5s;
}

.site-nav {
	position: sticky;
	top: 18px;
	z-index: 20;
	display: grid;
	grid-template-columns: 250px 1fr auto;
	align-items: center;
	gap: 28px;
	width: 100%;
	min-height: 74px;
	padding: 6px 0;
	border: 0;
	border-radius: 0;
	background: transparent;
	box-shadow: none;
	backdrop-filter: none;
}

.brand,
.nav-links,
.nav-actions,
.message-link,
.primary-button,
.slider-controls,
.dots,
.arrows,
.social-links,
.footer-legal {
	display: flex;
	align-items: center;
}

.brand {
	position: relative;
	width: max-content;
	gap: 8px;
}

.brand-mark {
	position: relative;
	color: var(--aqua);
	font-size: clamp(3rem, 4.7vw, 4.3rem);
	font-weight: 900;
	line-height: 0.72;
	letter-spacing: 0;
}

.brand-mark img {
	position: absolute;
	top: -0.12em;
	right: -0.26em;
	width: 0.32em;
	height: 0.32em;
	object-fit: contain;
	transform: rotate(10deg);
	filter: drop-shadow(0 5px 10px rgb(0 0 0 / 18%));
}

.brand-text {
	color: var(--aqua);
	font-size: clamp(1rem, 1.08vw, 1.28rem);
	font-weight: 800;
	line-height: 0.88;
}

.nav-links {
	justify-content: center;
	gap: clamp(20px, 3.8vw, 70px);
	color: #2d2d2d;
	font-size: clamp(0.95rem, 1.03vw, 1.1rem);
	font-weight: 700;
}

.nav-link-button {
	cursor: pointer;
	color: inherit;
	background: transparent;
	font-weight: inherit;
}

.nav-links a,
.nav-link-button,
.message-link {
	transition:
		color 180ms ease,
		transform 180ms ease;
}

.nav-links a:hover,
.nav-link-button:hover,
.message-link:hover {
	color: var(--aqua);
	transform: translateY(-1px);
}

.nav-actions {
	justify-content: flex-end;
	gap: 16px;
}

.message-link {
	gap: 9px;
	padding-right: 20px;
	border-right: 1px solid rgb(0 0 0 / 14%);
	color: #2d2d2d;
	font-size: 1rem;
	font-weight: 800;
}

.icon-button {
	width: 40px;
	aspect-ratio: 1;
	cursor: pointer;
	border-radius: 999px;
	color: #2d2d2d;
	background: transparent;
	transition:
		background 180ms ease,
		transform 180ms ease;
}

.icon-button:hover {
	background: rgb(150 11 10 / 8%);
	transform: translateY(-1px);
}

.primary-button {
	justify-content: center;
	min-height: 46px;
	padding: 0 24px;
	border-radius: 7px;
	color: #3f0808;
	background: var(--ink);
	box-shadow: 0 12px 28px rgb(251 131 82 / 28%);
	font-weight: 900;
	cursor: pointer;
	transition:
		transform 180ms ease,
		box-shadow 180ms ease,
		background 180ms ease;
}

.primary-button:hover {
	background: #ffab84;
	box-shadow: 0 18px 36px rgb(251 131 82 / 38%);
	transform: translateY(-2px);
}

.cover-panel {
	display: grid;
	grid-template-columns: minmax(0, 1fr) minmax(250px, 330px);
	gap: clamp(24px, 3vw, 52px);
	margin-top: 4px;
	padding: clamp(24px, 3vw, 38px);
	border: 1px solid rgb(255 255 255 / 14%);
	border-radius: 18px;
	background:
		linear-gradient(118deg, rgb(255 255 255 / 13%), rgb(255 255 255 / 3%) 42%), rgb(2 7 32 / 64%);
	box-shadow:
		var(--shadow-soft),
		inset 0 1px 0 rgb(255 255 255 / 11%);
	backdrop-filter: blur(28px) saturate(130%);
}

.cover-dropdown {
	position: absolute;
	z-index: 18;
	top: 132px;
	right: clamp(24px, 7vw, 160px);
	left: clamp(24px, 7vw, 160px);
	transform-origin: 78% 0;
	animation: menu-drop 360ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.cover-list {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 18px 36px;
	align-content: center;
}

.eyebrow {
	grid-column: 1 / -1;
	margin: 0 0 -8px;
	color: rgb(255 176 142 / 80%);
	font-size: 0.68rem;
	font-weight: 900;
	letter-spacing: 0.18em;
	text-transform: uppercase;
}

.cover-item {
	display: grid;
	grid-template-columns: 46px 1fr;
	gap: 14px;
	align-items: center;
	min-width: 0;
	cursor: pointer;
	padding: 8px;
	border-radius: 12px;
	color: white;
	background: transparent;
	text-align: left;
	transition:
		background 190ms ease,
		transform 190ms ease;
}

.cover-item:hover,
.cover-item.is-selected {
	background: rgb(251 131 82 / 12%);
	transform: translateX(4px);
}

.cover-icon {
	display: grid;
	place-items: center;
	width: 46px;
	aspect-ratio: 1;
	border-radius: 999px;
	background: rgb(255 255 255 / 95%);
	box-shadow: inset 0 -10px 18px rgb(8 19 70 / 8%);
}

.cover-icon img {
	width: 25px;
	height: 25px;
	object-fit: contain;
}

.cover-item strong,
.cover-item small {
	display: block;
}

.cover-item strong {
	margin-bottom: 4px;
	font-size: 0.92rem;
}

.cover-item small {
	max-width: 27ch;
	color: rgb(255 255 255 / 76%);
	font-size: 0.74rem;
	line-height: 1.26;
}

.cover-feature {
	position: relative;
	align-self: center;
	width: min(100%, 330px);
	height: clamp(280px, 24vw, 330px);
	justify-self: end;
	min-height: 300px;
	overflow: hidden;
	border-radius: 14px;
	box-shadow: 0 16px 42px rgb(0 0 0 / 18%);
}

.cover-feature::after,
.product-card::after,
.metric-photo::after {
	content: '';
	position: absolute;
	inset: 0;
	background: linear-gradient(180deg, transparent 62%, rgb(0 0 0 / 32%));
}

.cover-feature img,
.product-card > img:not(.product-butterfly),
.metric-card img {
	width: 100%;
	height: 100%;
	object-fit: cover;
}

.product-card[data-product='motor'] > img:not(.product-butterfly) {
	object-position: 52% 50%;
}

.product-card > img:not(.product-butterfly) {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 112%;
	object-fit: cover;
	transition:
		transform 760ms cubic-bezier(0.2, 0.8, 0.2, 1),
		filter 320ms ease;
}

.product-card[data-product='home'] > img:not(.product-butterfly) {
	object-position: center;
}

.cover-feature img {
	object-position: center;
}

.cover-feature span {
	position: absolute;
	z-index: 1;
	left: 26px;
	right: 22px;
	bottom: 24px;
	color: rgb(255 255 255 / 76%);
	font-size: clamp(2rem, 3vw, 2.1rem);
	font-weight: 900;
	line-height: 0.85;
	text-transform: uppercase;
	animation: content-pop 260ms ease both;
}

.landing-hero {
	width: min(100%, 680px);
	min-height: clamp(310px, 27vw, 390px);
	padding-top: clamp(38px, 7vw, 48px);
}

.hero-pill {
	display: inline-flex;
	min-height: 58px;
	align-items: center;
	margin: 0 0 42px;
	padding: 0 26px;
	border-radius: 999px;
	color: #fff;
	background: #960B0A;
	font-size: clamp(1rem, 1.12vw, 1.18rem);
	font-weight: 900;
}

.landing-hero h1 {
	max-width: 8.6ch;
	margin: 0 0 28px;
	color: #121212;
	font-size: clamp(1.8rem, 3vw, 3.3rem);
	font-weight: 900;
	line-height: 0.86;
	letter-spacing: -0.03em;
	text-transform: uppercase;
}

.landing-hero h1 span {
	display: block;
	color: var(--aqua);
}

.landing-hero > p:last-child {
	max-width: 560px;
	margin: 0;
	color: #2b2b2b;
	font-size: clamp(1.05rem, 1.34vw, 1.42rem);
	line-height: 1.12;
}

.product-stage {
	position: relative;
	margin: clamp(24px, 3vw, 40px) calc(var(--hero-gutter) * -1) 0;
}

.product-track {
	display: flex;
	gap: clamp(24px, 3vw, 48px);
	overflow-x: auto;
	padding: 0 var(--hero-gutter) 14px;
	scroll-snap-type: x mandatory;
	scrollbar-width: none;
}

.product-track::-webkit-scrollbar {
	display: none;
}

.product-card {
	position: relative;
	flex: 0 0 clamp(220px, 17vw, 290px);
	height: clamp(280px, 22vw, 340px);
	min-height: 0;
	overflow: hidden;
	cursor: pointer;
	border-radius: 18px;
	color: white;
	background: rgb(255 255 255 / 7%);
	box-shadow: none;
	scroll-snap-align: center;
	transform: translateZ(0);
	transition:
		transform 320ms cubic-bezier(0.2, 0.8, 0.2, 1),
		filter 240ms ease,
		box-shadow 240ms ease;
}

.product-card::before {
	content: '';
	position: absolute;
	inset: 0;
	z-index: 1;
	pointer-events: none;
	background:
		linear-gradient(116deg, transparent 0 38%, rgb(255 255 255 / 8%) 48%, transparent 58%),
		linear-gradient(180deg, rgb(255 255 255 / 3%), rgb(255 255 255 / 0%) 34%);
	mix-blend-mode: screen;
	opacity: 0;
	transform: translateX(-34%);
	transition:
		opacity 260ms ease,
		transform 760ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.product-card.is-active::before {
	animation: glass-sweep 4.8s cubic-bezier(0.2, 0.8, 0.2, 1) infinite;
}

.product-card-wide {
	flex-basis: clamp(440px, 40vw, 600px);
}

.product-card:hover,
.product-card.is-active {
	filter: saturate(1.03) contrast(1.01);
	box-shadow: inset 0 0 0 1px rgb(251 131 82 / 26%);
	transform: translateY(-4px);
}

.product-card:hover::before,
.product-card.is-active::before {
	opacity: 0.5;
	transform: translateX(10%);
}

.product-title {
	position: absolute;
	z-index: 2;
	left: clamp(22px, 3vw, 40px);
	bottom: clamp(52px, 4vw, 68px);
	font-size: clamp(2.35rem, 4.1vw, 4.25rem);
	font-weight: 900;
	line-height: 0.8;
	text-transform: uppercase;
}

.product-card.is-active .product-title {
	bottom: clamp(118px, 9vw, 150px);
}

.product-card:not(.product-card-wide) .product-title {
	font-size: clamp(1.75rem, 2.35vw, 2.55rem);
}

.product-card:not(.product-card-wide) .product-title {
	bottom: 34px;
}

.product-card .product-butterfly {
	position: static;
	display: inline-block;
	width: 0.78em;
	height: 0.78em;
	margin-top: -0.12em;
	margin-left: 0.04em;
	object-fit: contain;
	vertical-align: top;
	pointer-events: none;
	filter: drop-shadow(0 6px 10px rgb(0 0 0 / 28%));
	animation: butterfly-hover 3.8s ease-in-out infinite;
}

.product-divider {
	position: absolute;
	z-index: 2;
	right: clamp(22px, 3vw, 40px);
	bottom: clamp(91px, 7vw, 118px);
	left: clamp(22px, 3vw, 40px);
	height: 1px;
	background: rgb(255 255 255 / 38%);
}

.product-copy {
	position: absolute;
	z-index: 2;
	right: 22px;
	bottom: clamp(28px, 2.7vw, 42px);
	left: clamp(22px, 3vw, 40px);
	max-width: 36ch;
	color: rgb(255 255 255 / 88%);
	font-size: clamp(0.8rem, 0.88vw, 0.94rem);
	font-weight: 700;
	line-height: 1.1;
}

.product-card img {
	transition:
		transform 760ms cubic-bezier(0.2, 0.8, 0.2, 1),
		filter 320ms ease;
}

.slider-controls {
	justify-content: space-between;
	gap: 20px;
	margin-top: 16px;
	margin-bottom: clamp(26px, 3.5vw, 44px);
	padding: 0 var(--hero-gutter);
	position: relative;
	z-index: 6;
}

.dots {
	gap: 13px;
}

.dots button {
	width: 11px;
	aspect-ratio: 1;
	cursor: pointer;
	border-radius: 999px;
	background: rgb(251 131 82 / 36%);
	transition:
		width 180ms ease,
		background 180ms ease;
}

.dots .is-active {
	width: 28px;
	background: var(--aqua);
}

.arrows {
	gap: 22px;
	margin-left: auto;
}

.arrows button {
	cursor: pointer;
	color: var(--ink);
	background: transparent;
	font-size: 4rem;
	line-height: 1;
	transition:
		transform 180ms ease,
		color 180ms ease;
}

.arrows button:hover {
	color: var(--ink-deep);
	transform: translateY(-3px);
}

.service-band {
	position: relative;
	margin: clamp(18px, 3vw, 34px) calc(var(--hero-gutter) * -1) 0;
	padding: clamp(52px, 7vw, 86px) var(--hero-gutter) 0;
	color: white;
	background: var(--ink);
}

.service-band::before {
	content: '';
	position: absolute;
	top: -74px;
	right: 0;
	left: 0;
	height: 92px;
	background: var(--ink);
	clip-path: ellipse(72% 100% at 50% 100%);
}

.service-band h2 {
	max-width: 52ch;
	margin: 0 auto clamp(34px, 4.4vw, 56px);
	color: rgb(255 255 255 / 78%);
	font-size: clamp(1.42rem, 1.05vw, 1.02rem);
	font-weight: 400;
	line-height: 1.28;
	text-align: center;
}

.service-grid {
	display: grid;
	grid-template-columns: repeat(3, minmax(0, 1fr));
	gap: 34px;
}

.service-grid article {
	position: relative;
	isolation: isolate;
	min-height: 185px;
	padding: 20px clamp(20px, 3vw, 48px);
	border-left: 1px solid rgb(251 131 82 / 28%);
}

.service-grid article::after {
	content: '';
	position: absolute;
	z-index: -1;
	top: 4px;
	left: clamp(2px, 2vw, 26px);
	width: 106px;
	aspect-ratio: 1;
	border-radius: 999px;
	background: radial-gradient(circle, rgb(251 131 82 / 20%), transparent 68%);
	opacity: 0.34;
	transform: scale(0.82);
	animation: icon-glow 4.8s ease-in-out infinite;
}

.service-grid article:first-child {
	border-left: 0;
	padding-left: 0;
}

.line-icon {
	display: block;
	width: 58px;
	height: 58px;
	margin-bottom: 28px;
	border: 2px solid var(--aqua);
	opacity: 0.95;
}

.line-icon.sun {
	border-radius: 999px;
	box-shadow:
		0 0 0 13px rgb(251 131 82 / 0%),
		0 0 0 1px transparent;
	background: radial-gradient(
		circle,
		transparent 36%,
		var(--aqua) 37%,
		var(--aqua) 41%,
		transparent 42%
	);
	clip-path: polygon(
		48% 0,
		56% 0,
		56% 25%,
		48% 25%,
		48% 0,
		100% 48%,
		100% 56%,
		75% 56%,
		75% 48%,
		100% 48%,
		56% 100%,
		48% 100%,
		48% 75%,
		56% 75%,
		56% 100%,
		0 56%,
		0 48%,
		25% 48%,
		25% 56%,
		0 56%,
		48% 0
	);
}

.line-icon.folder {
	border-radius: 8px;
	border-top-left-radius: 4px;
}

.line-icon.planet {
	border-radius: 999px;
	transform: rotate(-24deg);
}

.line-icon.planet::after {
	content: '';
	display: block;
	width: 76px;
	height: 24px;
	margin: 15px 0 0 -11px;
	border: 2px solid var(--aqua);
	border-top-color: transparent;
	border-radius: 999px;
}

.service-icon {
	display: block;
	width: 58px;
	height: 58px;
	margin-bottom: 28px;
	object-fit: contain;
	transform-origin: 50% 50%;
	filter: drop-shadow(0 0 14px rgb(251 131 82 / 22%));
}

.service-icon-sun {
	animation: icon-sun-orbit 8.5s linear infinite;
}

.service-icon-folder {
	animation: icon-folder-float 5.8s cubic-bezier(0.45, 0, 0.2, 1) infinite;
}

.service-icon-orbit {
	animation: icon-orbit-spin 9s linear infinite;
}

.service-grid h3,
.metric-card h3,
.testimonial-card h3 {
	margin: 0;
}

.service-grid h3 {
	margin-bottom: 16px;
	font-size: 1.25rem;
}

.service-grid p {
	max-width: 28ch;
	margin: 0;
	color: rgb(255 255 255 / 82%);
	font-size: 1.05rem;
	line-height: 1.25;
}

.growth-section {
	position: relative;
	display: grid;
	justify-items: center;
	min-height: 560px;
	margin: 0 calc(var(--hero-gutter) * -1);
	padding: clamp(80px, 11vw, 12px) var(--hero-gutter) 32px;
	color: white;
	background: var(--ink);
	text-align: center;
}

.shape-left {
	left: -14%;
	bottom: -9%;
	width: clamp(270px, 42vw, 630px);
	opacity: 0.55;
	filter: brightness(0) saturate(100%) invert(13%) sepia(88%) saturate(3099%) hue-rotate(228deg)
		brightness(85%) contrast(105%);
}

.shape-right {
	right: -6%;
	top: 15%;
	width: clamp(240px, 34vw, 510px);
	opacity: 0.8;
	filter: brightness(0) saturate(100%) invert(13%) sepia(88%) saturate(3099%) hue-rotate(228deg)
		brightness(95%) contrast(110%);
	transform: rotate(8deg);
}

.wave {
	position: relative;
	width: 124px;
	height: 22px;
	margin-bottom: 42px;
	overflow: visible;
}

.wave::before,
.wave::after {
	content: '';
	position: absolute;
	inset: 50% auto auto 50%;
	width: 92px;
	aspect-ratio: 2.6;
	border: 2px solid rgb(251 131 82 / 70%);
	border-right-color: transparent;
	border-left-color: transparent;
	border-radius: 50%;
	transform: translate(-50%, -50%) scale(0.72);
	animation: ripple-ring 2.8s cubic-bezier(0.2, 0.8, 0.2, 1) infinite;
}

.wave::after {
	width: 126px;
	animation-delay: 1.05s;
	opacity: 0.5;
}

.growth-section h1 {
	max-width: 720px;
	margin: 0;
	color: white;
	font-size: clamp(2.9rem, 6.6vw, 5.0rem);
	font-weight: 900;
	line-height: 0.88;
	text-transform: uppercase;
}

.growth-butterfly {
	display: inline-block;
	width: 0.68em;
	height: 0.68em;
	margin-left: 0.08em;
	vertical-align: top;
	filter: drop-shadow(0 4px 8px rgb(0 0 0 / 24%));
}

.growth-section p {
	max-width: 490px;
	margin: 32px 0 34px;
	color: rgb(255 255 255 / 88%);
	font-size: clamp(1.06rem, 1.7vw, 1.42rem);
	font-weight: 700;
	line-height: 1.06;
}

.primary-button.large {
	gap: 12px;
	min-height: 62px;
	padding: 0 32px;
	color: #fff;
	font-size: 1.05rem;
	background: #540100;
}

.metric-grid {
	display: grid;
	grid-template-columns: repeat(6, minmax(0, 1fr));
	gap: 24px;
	margin: 0 calc(var(--hero-gutter) * -1);
	padding: 0 var(--hero-gutter) 16px;
	background: var(--ink);
}

.metric-card {
	position: relative;
	min-height: 240px;
	overflow: hidden;
	border: 1px solid rgb(255 255 255 / 15%);
	border-radius: 8px;
	background: rgb(255 255 255 / 8%);
	box-shadow: none;
}

.metric-card > div {
	position: relative;
	z-index: 1;
	display: flex;
	flex-direction: column;
	height: 100%;
	min-height: inherit;
	padding: 26px 32px;
}

.metric-card strong {
	color: white;
	font-size: clamp(1.9rem, 2.8vw, 3.2rem);
	font-weight: 900;
	line-height: 0.9;
}

.metric-card h3 {
	max-width: 12ch;
	margin-top: 12px;
	color: white;
	font-size: clamp(1rem, 1.35vw, 1.3rem);
	font-weight: 900;
	line-height: 1.03;
}

.metric-card p {
	max-width: 22ch;
	margin: auto 0 0;
	color: rgb(255 255 255 / 86%);
	font-size: 0.98rem;
	font-weight: 700;
	line-height: 1.06;
}

.metric-photo {
	grid-column: span 2;
}

.metric-photo img {
	position: absolute;
	inset: 0;
}

.metric-photo:first-child strong,
.metric-photo:first-child h3 {
	color: var(--orange);
}

.metric-card:nth-child(5) strong,
.metric-card:nth-child(5) h3 {
	color: var(--orange);
}

.metric-card:nth-child(5) img {
	object-position: center 44%;
}

.metric-photo::after {
	background: linear-gradient(90deg, rgb(0 0 0 / 42%), rgb(0 0 0 / 4%) 68%);
}

.metric-orange {
	grid-column: span 2;
	background: linear-gradient(135deg, #ff8752, #9c4e33);
}

.metric-blue {
	grid-column: span 2;
	background: radial-gradient(circle at top left, #5783a6, #092057 70%);
}

.metric-gold {
	grid-column: span 3;
	color: #1b0d0a;
	background: linear-gradient(135deg, #ffe3b1, #f0a323);
}

.metric-gold strong,
.metric-gold h3,
.metric-gold p {
	color: #9d1515;
}

.metric-gold img {
	position: absolute;
	right: 8%;
	bottom: 0;
	width: min(30%, 190px);
	height: auto;
	object-fit: contain;
}

.metric-gold > div {
	width: 70%;
}

.metric-card:nth-child(5) {
	grid-column: span 3;
}

.partner-section {
	position: relative;
	padding: 98px clamp(24px, 7vw, 160px) 92px;
	background: white;
	text-align: center;
}

.wave-divider {
	position: absolute;
	top: -70px;
	right: 0;
	left: 0;
	height: 140px;
	background: white;
	clip-path: ellipse(60% 44% at 50% 100%);
}

.partner-section h2 {
	position: relative;
	margin: 0 0 52px;
	font-size: clamp(1.5rem, 2.5vw, 2.4rem);
	font-weight: 400;
	line-height: 1.1;
}

.partner-marquee {
	overflow: hidden;
	padding-bottom: 82px;
}

.partner-marquee div {
	display: flex;
	width: max-content;
	align-items: center;
	gap: clamp(44px, 6vw, 86px);
	animation: marquee 26s linear infinite;
}

.partner-marquee img {
	max-width: 170px;
	max-height: 54px;
	filter: none;
	opacity: 1;
	object-fit: contain;
}

.floating-section-nav {
	position: fixed;
	bottom: 24px;
	left: 50%;
	z-index: 30;
	display: flex;
	width: max-content;
	max-width: calc(100% - 32px);
	align-items: center;
	gap: clamp(10px, 1.7vw, 24px);
	margin: 0;
	padding: 10px;
	border: 1px solid rgb(251 131 82 / 34%);
	border-radius: 999px;
	background:
		linear-gradient(135deg, rgb(251 131 82 / 24%), rgb(113 14 24 / 78%)), rgb(73 9 17 / 78%);
	box-shadow:
		0 18px 42px rgb(0 0 0 / 22%),
		inset 0 1px 0 rgb(255 255 255 / 22%);
	backdrop-filter: blur(20px) saturate(155%);
	opacity: 0;
	pointer-events: none;
	transform: translate(-50%, 22px) scale(0.96);
	transition:
		opacity 220ms ease,
		transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.floating-section-nav.is-visible {
	opacity: 1;
	pointer-events: auto;
	transform: translate(-50%, 0) scale(1);
}

.floating-section-nav a {
	display: inline-flex;
	min-height: 42px;
	align-items: center;
	justify-content: center;
	border-radius: 999px;
	padding: 0 8px;
	color: rgb(255 224 214 / 76%);
	font-size: clamp(0.86rem, 1.1vw, 1.08rem);
	font-weight: 900;
	white-space: nowrap;
	transition:
		color 180ms ease,
		background 180ms ease,
		transform 180ms ease;
}

.floating-section-nav a:hover {
	color: white;
	background: rgb(251 131 82 / 14%);
	transform: translateY(-1px);
}

.floating-section-nav .back-top {
	min-height: 48px;
	padding: 0 22px;
	color: #4a0808;
	background: var(--aqua);
	box-shadow: 0 10px 24px rgb(251 131 82 / 28%);
}

.proof-section {
	display: grid;
	grid-template-columns: minmax(280px, 0.86fr) minmax(420px, 1.14fr);
	gap: clamp(42px, 8vw, 140px);
	min-height: 610px;
	padding: 74px clamp(24px, 8vw, 170px) 86px;
	background: white;
}

.review-pill {
	display: inline-flex;
	align-items: center;
	gap: 7px;
	margin: 0 0 58px;
	padding: 12px 18px;
	border-radius: 8px;
	background: #fff1ec;
	font-weight: 900;
}

.review-pill span,
.stars {
	color: #ffb900;
}

.proof-copy h2 {
	margin: 0 0 26px;
	font-size: clamp(1.5rem, 2.4vw, 1.30rem);
	line-height: 1;
}

.proof-lead {
	max-width: 520px;
	margin: 0;
	font-size: clamp(2.2rem, 4vw, 2.0rem);
	line-height: 1.02;
}

.proof-copy small {
	display: block;
	max-width: 680px;
	margin-top: clamp(76px, 8vw, 0px);
	color: #676767;
	font-size: clamp(1rem, 1.2vw, 1.12rem);
	line-height: 1.3;
}

.testimonial-cloud {
	position: relative;
	min-height: 520px;
}

.testimonial-card {
	position: absolute;
	width: min(340px, 52vw);
	min-height: 188px;
	padding: 27px 30px;
	border: 1px solid rgb(0 0 0 / 10%);
	border-radius: 8px;
	box-shadow: 0 18px 42px rgb(0 0 0 / 7%);
	animation: card-float 7s ease-in-out infinite;
	animation-delay: calc(var(--card-index) * -1.2s);
}

.testimonial-card:nth-child(1) {
	top: 10px;
	left: 10%;
}

.testimonial-card:nth-child(2) {
	top: 86px;
	right: 0;
}

.testimonial-card:nth-child(3) {
	top: 222px;
	left: 0;
}

.testimonial-card:nth-child(4) {
	right: 9%;
	bottom: 10px;
}

.tone-cream {
	background: #fff9dd;
}

.tone-mint {
	background: #e9fbff;
}

.tone-rose {
	background: #fff0eb;
}

.tone-white {
	background: white;
}

.stars {
	margin-bottom: 24px;
	font-size: 1.1rem;
	letter-spacing: 0.35em;
}

.testimonial-card h3 {
	margin-bottom: 16px;
	font-size: 1.55rem;
	line-height: 1.04;
}

.testimonial-card p {
	margin: 0;
	font-size: 1rem;
	line-height: 1.08;
}

.faq-section {
	padding: 76px clamp(24px, 7vw, 160px) 122px;
	background: var(--paper);
}

.faq-inner {
	width: min(100%, 1000px);
	margin: 0 auto;
}

.faq-inner h2 {
	margin: 0 0 30px;
	font-size: clamp(1.7rem, 2.7vw, 2.6rem);
	line-height: 1;
}

.faq-inner > p {
	max-width: 760px;
	margin: 0 0 44px;
	font-size: clamp(1.1rem, 1.7vw, 1.55rem);
	line-height: 1.13;
}

.faq-list {
	border-top: 1px solid #dedcd7;
}

.faq-item {
	border-bottom: 1px solid #dedcd7;
}

.faq-item button {
	display: flex;
	width: 100%;
	align-items: center;
	justify-content: space-between;
	min-height: 78px;
	cursor: pointer;
	padding: 0 28px 0 14px;
	color: #090909;
	background: transparent;
	font-size: clamp(1.05rem, 1.7vw, 1.44rem);
	text-align: left;
}

.faq-item button span:last-child {
	font-size: 1.8rem;
	transition: transform 200ms ease;
}

.faq-item.is-open button span:last-child {
	transform: rotate(180deg);
}

.faq-item p {
	max-width: 740px;
	margin: -6px 0 28px 14px;
	color: #4d4d4d;
	font-size: 1.05rem;
	line-height: 1.35;
}

.site-footer {
	padding: 0 clamp(24px, 5vw, 90px) 60px;
	background: var(--paper);
}

.social-links {
	justify-content: center;
	gap: 46px;
	padding-bottom: 66px;
}

.social-links a {
	display: grid;
	place-items: center;
	width: 44px;
	height: 44px;
	transition:
		opacity 180ms ease,
		transform 180ms ease;
}

.social-links img {
	display: block;
	width: 36px;
	max-height: 36px;
	object-fit: contain;
}

.social-links a:hover {
	opacity: 0.72;
	transform: translateY(-3px);
}

.footer-legal {
	justify-content: space-between;
	gap: 28px;
	padding-top: 42px;
	border-top: 1px solid #dedcd7;
	font-size: 1.1rem;
	font-weight: 900;
}

.footer-legal span {
	margin-left: auto;
}

.reveal {
	opacity: 0;
	transform: translateY(28px);
	transition:
		opacity 620ms ease,
		transform 760ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.reveal.is-revealed {
	opacity: 1;
	transform: none;
}

.landing-hero,
.product-card,
.product-card > img:not(.product-butterfly),
.service-grid article,
.growth-section h1,
.growth-section .shape,
.metric-card,
.metric-card img,
.partner-section h2,
.partner-marquee,
.proof-copy,
.testimonial-card,
.faq-item {
	will-change: transform, opacity, filter;
}

@keyframes menu-drop {
	from {
		opacity: 0;
		transform: translateY(-12px) scale(0.98);
	}

	to {
		opacity: 1;
		transform: translateY(0) scale(1);
	}
}

@keyframes content-pop {
	from {
		opacity: 0;
		transform: translateY(10px);
	}

	to {
		opacity: 1;
		transform: translateY(0);
	}
}

@keyframes float-slow {
	0%,
	100% {
		transform: translate3d(0, 0, 0) rotate(0deg);
	}

	50% {
		transform: translate3d(22px, -28px, 0) rotate(6deg);
	}
}

@keyframes card-float {
	0%,
	100% {
		transform: translateY(0);
	}

	50% {
		transform: translateY(-12px);
	}
}

@keyframes glass-sweep {
	0%,
	42% {
		opacity: 0;
		transform: translateX(-42%);
	}

	58% {
		opacity: 0.48;
	}

	100% {
		opacity: 0;
		transform: translateX(34%);
	}
}

@keyframes icon-glow {
	0%,
	100% {
		opacity: 0.2;
		transform: scale(0.78);
	}

	50% {
		opacity: 0.46;
		transform: scale(1);
	}
}

@keyframes butterfly-hover {
	0%,
	100% {
		transform: translate3d(0, 0, 0) rotate(-6deg);
	}

	50% {
		transform: translate3d(5px, -7px, 0) rotate(8deg);
	}
}

@keyframes icon-sun-orbit {
	0% {
		transform: translate3d(0, 0, 0) rotate(0deg) scale(1);
	}

	35% {
		transform: translate3d(0, -4px, 0) rotate(126deg) scale(1.04);
	}

	70% {
		transform: translate3d(0, 2px, 0) rotate(252deg) scale(0.98);
	}

	100% {
		transform: translate3d(0, 0, 0) rotate(360deg) scale(1);
	}
}

@keyframes icon-folder-float {
	0%,
	100% {
		transform: translate3d(0, 0, 0) rotate(0deg);
	}

	40% {
		transform: translate3d(0, -8px, 0) rotate(-2deg);
	}

	72% {
		transform: translate3d(0, -3px, 0) rotate(2deg);
	}
}

@keyframes icon-orbit-spin {
	0% {
		transform: rotate(-18deg) scale(1);
	}

	50% {
		transform: rotate(162deg) scale(1.035);
	}

	100% {
		transform: rotate(342deg) scale(1);
	}
}

@keyframes ripple-ring {
	0% {
		opacity: 0;
		transform: translate(-50%, -50%) scale(0.54);
	}

	22% {
		opacity: 0.9;
	}

	100% {
		opacity: 0;
		transform: translate(-50%, -50%) scale(1.34);
	}
}

@keyframes marquee {
	to {
		transform: translateX(-50%);
	}
}

@media (prefers-reduced-motion: reduce) {
	*,
	*::before,
	*::after {
		scroll-behavior: auto !important;
		animation-duration: 1ms !important;
		animation-iteration-count: 1 !important;
		transition-duration: 1ms !important;
	}
}

@media (max-width: 1180px) {
	.site-nav {
		grid-template-columns: 1fr auto;
	}

	.nav-links {
		display: none;
	}

	.cover-panel,
	.proof-section {
		grid-template-columns: 1fr;
	}

	.cover-dropdown {
		top: 118px;
	}

	.product-card-wide {
		flex-basis: clamp(420px, 46vw, 620px);
	}

	.metric-grid {
		grid-template-columns: repeat(2, minmax(0, 1fr));
	}

	.metric-card,
	.metric-orange,
	.metric-blue,
	.metric-gold,
	.metric-card:nth-child(5) {
		grid-column: span 1;
	}
}

@media (max-width: 760px) {
	.hero-section {
		--hero-gutter: 16px;
		padding: 20px 16px 58px;
	}

	.site-nav {
		position: relative;
		top: 0;
		grid-template-columns: minmax(0, 1fr) auto;
		gap: 12px;
		min-height: 0;
		padding: 4px 0;
	}

	.brand {
		grid-column: 1 / -1;
		min-width: 0;
	}

	.brand-mark {
		font-size: clamp(3rem, 16vw, 4.2rem);
	}

	.brand-text {
		font-size: clamp(0.82rem, 4vw, 1rem);
	}

	.nav-links {
		display: none;
	}

	.nav-actions {
		grid-column: 1 / -1;
		display: flex;
		justify-content: space-between;
		gap: 10px;
		width: auto;
	}

	.message-link {
		display: none;
	}

	.icon-button {
		flex: 0 0 46px;
		width: 46px;
	}

	.primary-button {
		width: auto;
		min-width: 100px;
		min-height: 54px;
		padding: 0 12px;
		font-size: 0.95rem;
		line-height: 1.05;
		text-align: center;
		white-space: normal;
	}

	.cover-panel {
		grid-template-columns: 1fr;
		padding: 20px;
	}

	.cover-dropdown {
		position: relative;
		top: auto;
		right: auto;
		left: auto;
		margin-top: 18px;
	}

	.cover-feature {
		justify-self: stretch;
		width: 100%;
		height: 300px;
	}

	.landing-hero {
		min-height: 0;
		padding-top: 64px;
	}

	.hero-pill {
		min-height: 48px;
		margin-bottom: 30px;
		padding: 0 22px;
		font-size: 1rem;
	}

	.landing-hero h1 {
		max-width: 10ch;
		font-size: clamp(1.75rem, 8.8vw, 2.9rem);
	}

	.landing-hero > p:last-child {
		max-width: 18ch;
		font-size: clamp(1rem, 5.1vw, 1.32rem);
		line-height: 1.14;
	}

	.cover-list,
	.service-grid,
	.metric-grid {
		grid-template-columns: 1fr;
	}

	.cover-item {
		grid-template-columns: 42px 1fr;
	}

	.cover-feature {
		min-height: 290px;
	}

	.product-card {
		flex-basis: min(74vw, 300px);
		height: 360px;
		min-height: 0;
	}

	.product-card-wide {
		flex-basis: min(82vw, 370px);
	}

	.social-links {
		gap: 26px;
		padding-bottom: 46px;
	}

	.social-links a {
		width: 34px;
		height: 34px;
	}

	.social-links img {
		width: 30px;
		max-height: 30px;
	}

	.service-band h2 {
		max-width: 100%;
	}

	.service-grid article,
	.service-grid article:first-child {
		min-height: 0;
		padding: 0 0 26px;
		border-left: 0;
		border-bottom: 1px solid rgb(251 131 82 / 22%);
	}

	.growth-section h1 {
		font-size: clamp(3.6rem, 17vw, 5.8rem);
	}

	.metric-card > div,
	.metric-gold > div {
		width: 100%;
	}

	.metric-gold img {
		opacity: 0.25;
	}

	.partner-section,
	.proof-section,
	.faq-section {
		padding-right: 18px;
		padding-left: 18px;
	}

	.testimonial-cloud {
		display: grid;
		gap: 16px;
		min-height: 0;
	}

	.testimonial-card,
	.testimonial-card:nth-child(n) {
		position: static;
		width: 100%;
	}

	.footer-legal {
		flex-direction: column;
		align-items: flex-start;
	}

	.footer-legal span {
		margin-left: 0;
	}

	.floating-section-nav {
		display: none;
	}
}

.scroll-progress {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	height: 5px;
	background: var(--aqua);
	transform-origin: 0;
	transform: scaleX(0);
	z-index: 999;
	transition: transform 100ms linear;
}

@import 'tailwindcss';
@plugin '@tailwindcss/forms';
@plugin '@tailwindcss/typography';

@font-face {
	font-family: 'Lato';
	font-style: normal;
	font-weight: 300;
	font-display: swap;
	src: url('/theme/assets/fonts/Lato/Lato-Light.woff2') format('woff2');
}

@font-face {
	font-family: 'Lato';
	font-style: normal;
	font-weight: 400;
	font-display: swap;
	src: url('/theme/assets/fonts/Lato/Lato-Regular.woff2') format('woff2');
}

@font-face {
	font-family: 'Lato';
	font-style: normal;
	font-weight: 700;
	font-display: swap;
	src: url('/theme/assets/fonts/Lato/Lato-Bold.woff2') format('woff2');
}

@font-face {
	font-family: 'Lato';
	font-style: normal;
	font-weight: 900;
	font-display: swap;
	src: url('/theme/assets/fonts/Lato/Lato-Black.woff2') format('woff2');
}

:root {
	--ink: #960B0A;
	--ink-deep: #5a0707;
	--blue: #960b0a;
	--blue-soft: #b91818;
	--aqua: #fb8352;
	--aqua-strong: #ff9f73;
	--orange: #fb8352;
	--gold: #f7b23a;
	--paper: #fbfaf7;
	--muted: #68707c;
	--line: rgb(255 255 255 / 16%);
	--shadow-soft: 0 26px 80px rgb(0 0 0 / 28%);
	--shadow-card: 0 18px 52px rgb(0 0 0 / 18%);
}

* {
	box-sizing: border-box;
}

html {
	scroll-behavior: smooth;
}

body {
	margin: 0;
	background: var(--ink);
	color: #0b0d17;
	font-family: 'Lato', Arial, sans-serif;
	-webkit-font-smoothing: antialiased;
	text-rendering: geometricPrecision;
}

img {
	display: block;
	max-width: 100%;
}

a {
	color: inherit;
	text-decoration: none;
}

button {
	border: 0;
	font: inherit;
}

.site-shell {
	width: min(100%, 1720px);
	margin: 0 auto;
	overflow: hidden;
	background: var(--paper);
	box-shadow: 0 0 0 1px rgb(4 13 71 / 8%);
}

.hero-section {
	--hero-gutter: clamp(24px, 7vw, 160px);
	position: relative;
	isolation: isolate;
	overflow: hidden;
	padding: 42px var(--hero-gutter) 64px;
	color: #131313;
	background:
		repeating-linear-gradient(
			90deg,
			rgb(251 131 82 / 12%) 0,
			rgb(251 131 82 / 12%) 1px,
			transparent 1px,
			transparent 68px
		),
		repeating-linear-gradient(
			0deg,
			rgb(251 131 82 / 12%) 0,
			rgb(251 131 82 / 12%) 1px,
			transparent 1px,
			transparent 68px
		),
		radial-gradient(circle at 22% 16%, rgb(251 131 82 / 11%), transparent 26rem),
		radial-gradient(circle at 78% 36%, rgb(150 11 10 / 9%), transparent 30rem),
		linear-gradient(180deg, #fff 0%, #fff 100%);
}

.ambient,
.shape {
	pointer-events: none;
	position: absolute;
	z-index: -1;
}

.ambient {
	width: 34rem;
	height: 34rem;
	border: 1px solid rgb(251 131 82 / 8%);
	border-radius: 999px;
	background: radial-gradient(circle, rgb(251 131 82 / 8%), transparent 66%);
	filter: blur(4px);
	animation: float-slow 13s ease-in-out infinite;
}

.ambient-one {
	top: 7rem;
	left: -18rem;
}

.ambient-two {
	right: -16rem;
	bottom: 42rem;
	animation-delay: -5s;
}

.site-nav {
	position: sticky;
	top: 18px;
	z-index: 20;
	display: grid;
	grid-template-columns: 250px 1fr auto;
	align-items: center;
	gap: 28px;
	width: 100%;
	min-height: 74px;
	padding: 6px 0;
	border: 0;
	border-radius: 0;
	background: transparent;
	box-shadow: none;
	backdrop-filter: none;
}

.brand,
.nav-links,
.nav-actions,
.message-link,
.primary-button,
.slider-controls,
.dots,
.arrows,
.social-links,
.footer-legal {
	display: flex;
	align-items: center;
}

.brand {
	position: relative;
	width: max-content;
	gap: 8px;
}

.brand-mark {
	position: relative;
	color: var(--aqua);
	font-size: clamp(3rem, 4.7vw, 4.3rem);
	font-weight: 900;
	line-height: 0.72;
	letter-spacing: 0;
}

.brand-mark img {
	position: absolute;
	top: -0.12em;
	right: -0.26em;
	width: 0.32em;
	height: 0.32em;
	object-fit: contain;
	transform: rotate(10deg);
	filter: drop-shadow(0 5px 10px rgb(0 0 0 / 18%));
}

.brand-text {
	color: var(--aqua);
	font-size: clamp(1rem, 1.08vw, 1.28rem);
	font-weight: 800;
	line-height: 0.88;
}

.nav-links {
	justify-content: center;
	gap: clamp(20px, 3.8vw, 70px);
	color: #2d2d2d;
	font-size: clamp(0.95rem, 1.03vw, 1.1rem);
	font-weight: 700;
}

.nav-link-button {
	cursor: pointer;
	color: inherit;
	background: transparent;
	font-weight: inherit;
}

.nav-links a,
.nav-link-button,
.message-link {
	transition:
		color 180ms ease,
		transform 180ms ease;
}

.nav-links a:hover,
.nav-link-button:hover,
.message-link:hover {
	color: var(--aqua);
	transform: translateY(-1px);
}

.nav-actions {
	justify-content: flex-end;
	gap: 16px;
}

.message-link {
	gap: 9px;
	padding-right: 20px;
	border-right: 1px solid rgb(0 0 0 / 14%);
	color: #2d2d2d;
	font-size: 1rem;
	font-weight: 800;
}

.icon-button {
	width: 40px;
	aspect-ratio: 1;
	cursor: pointer;
	border-radius: 999px;
	color: #2d2d2d;
	background: transparent;
	transition:
		background 180ms ease,
		transform 180ms ease;
}

.icon-button:hover {
	background: rgb(150 11 10 / 8%);
	transform: translateY(-1px);
}

.primary-button {
	justify-content: center;
	min-height: 46px;
	padding: 0 24px;
	border-radius: 7px;
	color: #3f0808;
	background: var(--ink);
	box-shadow: 0 12px 28px rgb(251 131 82 / 28%);
	font-weight: 900;
	cursor: pointer;
	transition:
		transform 180ms ease,
		box-shadow 180ms ease,
		background 180ms ease;
}

.primary-button:hover {
	background: #ffab84;
	box-shadow: 0 18px 36px rgb(251 131 82 / 38%);
	transform: translateY(-2px);
}

.cover-panel {
	display: grid;
	grid-template-columns: minmax(0, 1fr) minmax(250px, 330px);
	gap: clamp(24px, 3vw, 52px);
	margin-top: 4px;
	padding: clamp(24px, 3vw, 38px);
	border: 1px solid rgb(255 255 255 / 14%);
	border-radius: 18px;
	background:
		linear-gradient(118deg, rgb(255 255 255 / 13%), rgb(255 255 255 / 3%) 42%), rgb(2 7 32 / 64%);
	box-shadow:
		var(--shadow-soft),
		inset 0 1px 0 rgb(255 255 255 / 11%);
	backdrop-filter: blur(28px) saturate(130%);
}

.cover-dropdown {
	position: absolute;
	z-index: 18;
	top: 132px;
	right: clamp(24px, 7vw, 160px);
	left: clamp(24px, 7vw, 160px);
	transform-origin: 78% 0;
	animation: menu-drop 360ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.cover-list {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 18px 36px;
	align-content: center;
}

.eyebrow {
	grid-column: 1 / -1;
	margin: 0 0 -8px;
	color: rgb(255 176 142 / 80%);
	font-size: 0.68rem;
	font-weight: 900;
	letter-spacing: 0.18em;
	text-transform: uppercase;
}

.cover-item {
	display: grid;
	grid-template-columns: 46px 1fr;
	gap: 14px;
	align-items: center;
	min-width: 0;
	cursor: pointer;
	padding: 8px;
	border-radius: 12px;
	color: white;
	background: transparent;
	text-align: left;
	transition:
		background 190ms ease,
		transform 190ms ease;
}

.cover-item:hover,
.cover-item.is-selected {
	background: rgb(251 131 82 / 12%);
	transform: translateX(4px);
}

.cover-icon {
	display: grid;
	place-items: center;
	width: 46px;
	aspect-ratio: 1;
	border-radius: 999px;
	background: rgb(255 255 255 / 95%);
	box-shadow: inset 0 -10px 18px rgb(8 19 70 / 8%);
}

.cover-icon img {
	width: 25px;
	height: 25px;
	object-fit: contain;
}

.cover-item strong,
.cover-item small {
	display: block;
}

.cover-item strong {
	margin-bottom: 4px;
	font-size: 0.92rem;
}

.cover-item small {
	max-width: 27ch;
	color: rgb(255 255 255 / 76%);
	font-size: 0.74rem;
	line-height: 1.26;
}

.cover-feature {
	position: relative;
	align-self: center;
	width: min(100%, 330px);
	height: clamp(280px, 24vw, 330px);
	justify-self: end;
	min-height: 300px;
	overflow: hidden;
	border-radius: 14px;
	box-shadow: 0 16px 42px rgb(0 0 0 / 18%);
}

.cover-feature::after,
.product-card::after,
.metric-photo::after {
	content: '';
	position: absolute;
	inset: 0;
	background: linear-gradient(180deg, transparent 62%, rgb(0 0 0 / 32%));
}

.cover-feature img,
.product-card > img:not(.product-butterfly),
.metric-card img {
	width: 100%;
	height: 100%;
	object-fit: cover;
}

.product-card[data-product='motor'] > img:not(.product-butterfly) {
	object-position: 52% 50%;
}

.product-card > img:not(.product-butterfly) {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 112%;
	object-fit: cover;
	transition:
		transform 760ms cubic-bezier(0.2, 0.8, 0.2, 1),
		filter 320ms ease;
}

.product-card[data-product='home'] > img:not(.product-butterfly) {
	object-position: center;
}

.cover-feature img {
	object-position: center;
}

.cover-feature span {
	position: absolute;
	z-index: 1;
	left: 26px;
	right: 22px;
	bottom: 24px;
	color: rgb(255 255 255 / 76%);
	font-size: clamp(2rem, 3vw, 2.1rem);
	font-weight: 900;
	line-height: 0.85;
	text-transform: uppercase;
	animation: content-pop 260ms ease both;
}

.landing-hero {
	width: min(100%, 680px);
	min-height: clamp(310px, 27vw, 390px);
	padding-top: clamp(38px, 7vw, 48px);
}

.hero-pill {
	display: inline-flex;
	min-height: 58px;
	align-items: center;
	margin: 0 0 42px;
	padding: 0 26px;
	border-radius: 999px;
	color: #fff;
	background: #960B0A;
	font-size: clamp(1rem, 1.12vw, 1.18rem);
	font-weight: 900;
}

.landing-hero h1 {
	max-width: 8.6ch;
	margin: 0 0 28px;
	color: #121212;
	font-size: clamp(1.8rem, 3vw, 3.3rem);
	font-weight: 900;
	line-height: 0.86;
	letter-spacing: -0.03em;
	text-transform: uppercase;
}

.landing-hero h1 span {
	display: block;
	color: var(--aqua);
}

.landing-hero > p:last-child {
	max-width: 560px;
	margin: 0;
	color: #2b2b2b;
	font-size: clamp(1.05rem, 1.34vw, 1.42rem);
	line-height: 1.12;
}

.product-stage {
	position: relative;
	margin: clamp(24px, 3vw, 40px) calc(var(--hero-gutter) * -1) 0;
}

.product-track {
	display: flex;
	gap: clamp(24px, 3vw, 48px);
	overflow-x: auto;
	padding: 0 var(--hero-gutter) 14px;
	scroll-snap-type: x mandatory;
	scrollbar-width: none;
}

.product-track::-webkit-scrollbar {
	display: none;
}

.product-card {
	position: relative;
	flex: 0 0 clamp(220px, 17vw, 290px);
	height: clamp(280px, 22vw, 340px);
	min-height: 0;
	overflow: hidden;
	cursor: pointer;
	border-radius: 18px;
	color: white;
	background: rgb(255 255 255 / 7%);
	box-shadow: none;
	scroll-snap-align: center;
	transform: translateZ(0);
	transition:
		transform 320ms cubic-bezier(0.2, 0.8, 0.2, 1),
		filter 240ms ease,
		box-shadow 240ms ease;
}

.product-card::before {
	content: '';
	position: absolute;
	inset: 0;
	z-index: 1;
	pointer-events: none;
	background:
		linear-gradient(116deg, transparent 0 38%, rgb(255 255 255 / 8%) 48%, transparent 58%),
		linear-gradient(180deg, rgb(255 255 255 / 3%), rgb(255 255 255 / 0%) 34%);
	mix-blend-mode: screen;
	opacity: 0;
	transform: translateX(-34%);
	transition:
		opacity 260ms ease,
		transform 760ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.product-card.is-active::before {
	animation: glass-sweep 4.8s cubic-bezier(0.2, 0.8, 0.2, 1) infinite;
}

.product-card-wide {
	flex-basis: clamp(440px, 40vw, 600px);
}

.product-card:hover,
.product-card.is-active {
	filter: saturate(1.03) contrast(1.01);
	box-shadow: inset 0 0 0 1px rgb(251 131 82 / 26%);
	transform: translateY(-4px);
}

.product-card:hover::before,
.product-card.is-active::before {
	opacity: 0.5;
	transform: translateX(10%);
}

.product-title {
	position: absolute;
	z-index: 2;
	left: clamp(22px, 3vw, 40px);
	bottom: clamp(52px, 4vw, 68px);
	font-size: clamp(2.35rem, 4.1vw, 4.25rem);
	font-weight: 900;
	line-height: 0.8;
	text-transform: uppercase;
}

.product-card.is-active .product-title {
	bottom: clamp(118px, 9vw, 150px);
}

.product-card:not(.product-card-wide) .product-title {
	font-size: clamp(1.75rem, 2.35vw, 2.55rem);
}

.product-card:not(.product-card-wide) .product-title {
	bottom: 34px;
}

.product-card .product-butterfly {
	position: static;
	display: inline-block;
	width: 0.78em;
	height: 0.78em;
	margin-top: -0.12em;
	margin-left: 0.04em;
	object-fit: contain;
	vertical-align: top;
	pointer-events: none;
	filter: drop-shadow(0 6px 10px rgb(0 0 0 / 28%));
	animation: butterfly-hover 3.8s ease-in-out infinite;
}

.product-divider {
	position: absolute;
	z-index: 2;
	right: clamp(22px, 3vw, 40px);
	bottom: clamp(91px, 7vw, 118px);
	left: clamp(22px, 3vw, 40px);
	height: 1px;
	background: rgb(255 255 255 / 38%);
}

.product-copy {
	position: absolute;
	z-index: 2;
	right: 22px;
	bottom: clamp(28px, 2.7vw, 42px);
	left: clamp(22px, 3vw, 40px);
	max-width: 36ch;
	color: rgb(255 255 255 / 88%);
	font-size: clamp(0.8rem, 0.88vw, 0.94rem);
	font-weight: 700;
	line-height: 1.1;
}

.product-card img {
	transition:
		transform 760ms cubic-bezier(0.2, 0.8, 0.2, 1),
		filter 320ms ease;
}

.slider-controls {
	justify-content: space-between;
	gap: 20px;
	margin-top: 16px;
	margin-bottom: clamp(26px, 3.5vw, 44px);
	padding: 0 var(--hero-gutter);
	position: relative;
	z-index: 6;
}

.dots {
	gap: 13px;
}

.dots button {
	width: 11px;
	aspect-ratio: 1;
	cursor: pointer;
	border-radius: 999px;
	background: rgb(251 131 82 / 36%);
	transition:
		width 180ms ease,
		background 180ms ease;
}

.dots .is-active {
	width: 28px;
	background: var(--aqua);
}

.arrows {
	gap: 22px;
	margin-left: auto;
}

.arrows button {
	cursor: pointer;
	color: var(--ink);
	background: transparent;
	font-size: 4rem;
	line-height: 1;
	transition:
		transform 180ms ease,
		color 180ms ease;
}

.arrows button:hover {
	color: var(--ink-deep);
	transform: translateY(-3px);
}

.service-band {
	position: relative;
	margin: clamp(18px, 3vw, 34px) calc(var(--hero-gutter) * -1) 0;
	padding: clamp(52px, 7vw, 86px) var(--hero-gutter) 0;
	color: white;
	background: var(--ink);
}

.service-band::before {
	content: '';
	position: absolute;
	top: -74px;
	right: 0;
	left: 0;
	height: 92px;
	background: var(--ink);
	clip-path: ellipse(72% 100% at 50% 100%);
}

.service-band h2 {
	max-width: 52ch;
	margin: 0 auto clamp(34px, 4.4vw, 56px);
	color: rgb(255 255 255 / 78%);
	font-size: clamp(1.42rem, 1.05vw, 1.02rem);
	font-weight: 400;
	line-height: 1.28;
	text-align: center;
}

.service-grid {
	display: grid;
	grid-template-columns: repeat(3, minmax(0, 1fr));
	gap: 34px;
}

.service-grid article {
	position: relative;
	isolation: isolate;
	min-height: 185px;
	padding: 20px clamp(20px, 3vw, 48px);
	border-left: 1px solid rgb(251 131 82 / 28%);
}

.service-grid article::after {
	content: '';
	position: absolute;
	z-index: -1;
	top: 4px;
	left: clamp(2px, 2vw, 26px);
	width: 106px;
	aspect-ratio: 1;
	border-radius: 999px;
	background: radial-gradient(circle, rgb(251 131 82 / 20%), transparent 68%);
	opacity: 0.34;
	transform: scale(0.82);
	animation: icon-glow 4.8s ease-in-out infinite;
}

.service-grid article:first-child {
	border-left: 0;
	padding-left: 0;
}

.line-icon {
	display: block;
	width: 58px;
	height: 58px;
	margin-bottom: 28px;
	border: 2px solid var(--aqua);
	opacity: 0.95;
}

.line-icon.sun {
	border-radius: 999px;
	box-shadow:
		0 0 0 13px rgb(251 131 82 / 0%),
		0 0 0 1px transparent;
	background: radial-gradient(
		circle,
		transparent 36%,
		var(--aqua) 37%,
		var(--aqua) 41%,
		transparent 42%
	);
	clip-path: polygon(
		48% 0,
		56% 0,
		56% 25%,
		48% 25%,
		48% 0,
		100% 48%,
		100% 56%,
		75% 56%,
		75% 48%,
		100% 48%,
		56% 100%,
		48% 100%,
		48% 75%,
		56% 75%,
		56% 100%,
		0 56%,
		0 48%,
		25% 48%,
		25% 56%,
		0 56%,
		48% 0
	);
}

.line-icon.folder {
	border-radius: 8px;
	border-top-left-radius: 4px;
}

.line-icon.planet {
	border-radius: 999px;
	transform: rotate(-24deg);
}

.line-icon.planet::after {
	content: '';
	display: block;
	width: 76px;
	height: 24px;
	margin: 15px 0 0 -11px;
	border: 2px solid var(--aqua);
	border-top-color: transparent;
	border-radius: 999px;
}

.service-icon {
	display: block;
	width: 58px;
	height: 58px;
	margin-bottom: 28px;
	object-fit: contain;
	transform-origin: 50% 50%;
	filter: drop-shadow(0 0 14px rgb(251 131 82 / 22%));
}

.service-icon-sun {
	animation: icon-sun-orbit 8.5s linear infinite;
}

.service-icon-folder {
	animation: icon-folder-float 5.8s cubic-bezier(0.45, 0, 0.2, 1) infinite;
}

.service-icon-orbit {
	animation: icon-orbit-spin 9s linear infinite;
}

.service-grid h3,
.metric-card h3,
.testimonial-card h3 {
	margin: 0;
}

.service-grid h3 {
	margin-bottom: 16px;
	font-size: 1.25rem;
}

.service-grid p {
	max-width: 28ch;
	margin: 0;
	color: rgb(255 255 255 / 82%);
	font-size: 1.05rem;
	line-height: 1.25;
}

.growth-section {
	position: relative;
	display: grid;
	justify-items: center;
	min-height: 560px;
	margin: 0 calc(var(--hero-gutter) * -1);
	padding: clamp(80px, 11vw, 12px) var(--hero-gutter) 32px;
	color: white;
	background: var(--ink);
	text-align: center;
}

.shape-left {
	left: -14%;
	bottom: -9%;
	width: clamp(270px, 42vw, 630px);
	opacity: 0.55;
	filter: brightness(0) saturate(100%) invert(13%) sepia(88%) saturate(3099%) hue-rotate(228deg)
		brightness(85%) contrast(105%);
}

.shape-right {
	right: -6%;
	top: 15%;
	width: clamp(240px, 34vw, 510px);
	opacity: 0.8;
	filter: brightness(0) saturate(100%) invert(13%) sepia(88%) saturate(3099%) hue-rotate(228deg)
		brightness(95%) contrast(110%);
	transform: rotate(8deg);
}

.wave {
	position: relative;
	width: 124px;
	height: 22px;
	margin-bottom: 42px;
	overflow: visible;
}

.wave::before,
.wave::after {
	content: '';
	position: absolute;
	inset: 50% auto auto 50%;
	width: 92px;
	aspect-ratio: 2.6;
	border: 2px solid rgb(251 131 82 / 70%);
	border-right-color: transparent;
	border-left-color: transparent;
	border-radius: 50%;
	transform: translate(-50%, -50%) scale(0.72);
	animation: ripple-ring 2.8s cubic-bezier(0.2, 0.8, 0.2, 1) infinite;
}

.wave::after {
	width: 126px;
	animation-delay: 1.05s;
	opacity: 0.5;
}

.growth-section h1 {
	max-width: 720px;
	margin: 0;
	color: white;
	font-size: clamp(2.9rem, 6.6vw, 5.0rem);
	font-weight: 900;
	line-height: 0.88;
	text-transform: uppercase;
}

.growth-butterfly {
	display: inline-block;
	width: 0.68em;
	height: 0.68em;
	margin-left: 0.08em;
	vertical-align: top;
	filter: drop-shadow(0 4px 8px rgb(0 0 0 / 24%));
}

.growth-section p {
	max-width: 490px;
	margin: 32px 0 34px;
	color: rgb(255 255 255 / 88%);
	font-size: clamp(1.06rem, 1.7vw, 1.42rem);
	font-weight: 700;
	line-height: 1.06;
}

.primary-button.large {
	gap: 12px;
	min-height: 62px;
	padding: 0 32px;
	color: #fff;
	font-size: 1.05rem;
	background: #540100;
}

.metric-grid {
	display: grid;
	grid-template-columns: repeat(6, minmax(0, 1fr));
	gap: 24px;
	margin: 0 calc(var(--hero-gutter) * -1);
	padding: 0 var(--hero-gutter) 16px;
	background: var(--ink);
}

.metric-card {
	position: relative;
	min-height: 240px;
	overflow: hidden;
	border: 1px solid rgb(255 255 255 / 15%);
	border-radius: 8px;
	background: rgb(255 255 255 / 8%);
	box-shadow: none;
}

.metric-card > div {
	position: relative;
	z-index: 1;
	display: flex;
	flex-direction: column;
	height: 100%;
	min-height: inherit;
	padding: 26px 32px;
}

.metric-card strong {
	color: white;
	font-size: clamp(1.9rem, 2.8vw, 3.2rem);
	font-weight: 900;
	line-height: 0.9;
}

.metric-card h3 {
	max-width: 12ch;
	margin-top: 12px;
	color: white;
	font-size: clamp(1rem, 1.35vw, 1.3rem);
	font-weight: 900;
	line-height: 1.03;
}

.metric-card p {
	max-width: 22ch;
	margin: auto 0 0;
	color: rgb(255 255 255 / 86%);
	font-size: 0.98rem;
	font-weight: 700;
	line-height: 1.06;
}

.metric-photo {
	grid-column: span 2;
}

.metric-photo img {
	position: absolute;
	inset: 0;
}

.metric-photo:first-child strong,
.metric-photo:first-child h3 {
	color: var(--orange);
}

.metric-card:nth-child(5) strong,
.metric-card:nth-child(5) h3 {
	color: var(--orange);
}

.metric-card:nth-child(5) img {
	object-position: center 44%;
}

.metric-photo::after {
	background: linear-gradient(90deg, rgb(0 0 0 / 42%), rgb(0 0 0 / 4%) 68%);
}

.metric-orange {
	grid-column: span 2;
	background: linear-gradient(135deg, #ff8752, #9c4e33);
}

.metric-blue {
	grid-column: span 2;
	background: radial-gradient(circle at top left, #5783a6, #092057 70%);
}

.metric-gold {
	grid-column: span 3;
	color: #1b0d0a;
	background: linear-gradient(135deg, #ffe3b1, #f0a323);
}

.metric-gold strong,
.metric-gold h3,
.metric-gold p {
	color: #9d1515;
}

.metric-gold img {
	position: absolute;
	right: 8%;
	bottom: 0;
	width: min(30%, 190px);
	height: auto;
	object-fit: contain;
}

.metric-gold > div {
	width: 70%;
}

.metric-card:nth-child(5) {
	grid-column: span 3;
}

.partner-section {
	position: relative;
	padding: 98px clamp(24px, 7vw, 160px) 92px;
	background: white;
	text-align: center;
}

.wave-divider {
	position: absolute;
	top: -70px;
	right: 0;
	left: 0;
	height: 140px;
	background: white;
	clip-path: ellipse(60% 44% at 50% 100%);
}

.partner-section h2 {
	position: relative;
	margin: 0 0 52px;
	font-size: clamp(1.5rem, 2.5vw, 2.4rem);
	font-weight: 400;
	line-height: 1.1;
}

.partner-marquee {
	overflow: hidden;
	padding-bottom: 82px;
}

.partner-marquee div {
	display: flex;
	width: max-content;
	align-items: center;
	gap: clamp(44px, 6vw, 86px);
	animation: marquee 26s linear infinite;
}

.partner-marquee img {
	max-width: 170px;
	max-height: 54px;
	filter: none;
	opacity: 1;
	object-fit: contain;
}

.floating-section-nav {
	position: fixed;
	bottom: 24px;
	left: 50%;
	z-index: 30;
	display: flex;
	width: max-content;
	max-width: calc(100% - 32px);
	align-items: center;
	gap: clamp(10px, 1.7vw, 24px);
	margin: 0;
	padding: 10px;
	border: 1px solid rgb(251 131 82 / 34%);
	border-radius: 999px;
	background:
		linear-gradient(135deg, rgb(251 131 82 / 24%), rgb(113 14 24 / 78%)), rgb(73 9 17 / 78%);
	box-shadow:
		0 18px 42px rgb(0 0 0 / 22%),
		inset 0 1px 0 rgb(255 255 255 / 22%);
	backdrop-filter: blur(20px) saturate(155%);
	opacity: 0;
	pointer-events: none;
	transform: translate(-50%, 22px) scale(0.96);
	transition:
		opacity 220ms ease,
		transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.floating-section-nav.is-visible {
	opacity: 1;
	pointer-events: auto;
	transform: translate(-50%, 0) scale(1);
}

.floating-section-nav a {
	display: inline-flex;
	min-height: 42px;
	align-items: center;
	justify-content: center;
	border-radius: 999px;
	padding: 0 8px;
	color: rgb(255 224 214 / 76%);
	font-size: clamp(0.86rem, 1.1vw, 1.08rem);
	font-weight: 900;
	white-space: nowrap;
	transition:
		color 180ms ease,
		background 180ms ease,
		transform 180ms ease;
}

.floating-section-nav a:hover {
	color: white;
	background: rgb(251 131 82 / 14%);
	transform: translateY(-1px);
}

.floating-section-nav .back-top {
	min-height: 48px;
	padding: 0 22px;
	color: #4a0808;
	background: var(--aqua);
	box-shadow: 0 10px 24px rgb(251 131 82 / 28%);
}

.proof-section {
	display: grid;
	grid-template-columns: minmax(280px, 0.86fr) minmax(420px, 1.14fr);
	gap: clamp(42px, 8vw, 140px);
	min-height: 610px;
	padding: 74px clamp(24px, 8vw, 170px) 86px;
	background: white;
}

.review-pill {
	display: inline-flex;
	align-items: center;
	gap: 7px;
	margin: 0 0 58px;
	padding: 12px 18px;
	border-radius: 8px;
	background: #fff1ec;
	font-weight: 900;
}

.review-pill span,
.stars {
	color: #ffb900;
}

.proof-copy h2 {
	margin: 0 0 26px;
	font-size: clamp(1.5rem, 2.4vw, 1.30rem);
	line-height: 1;
}

.proof-lead {
	max-width: 520px;
	margin: 0;
	font-size: clamp(2.2rem, 4vw, 2.0rem);
	line-height: 1.02;
}

.proof-copy small {
	display: block;
	max-width: 680px;
	margin-top: clamp(76px, 8vw, 0px);
	color: #676767;
	font-size: clamp(1rem, 1.2vw, 1.12rem);
	line-height: 1.3;
}

.testimonial-cloud {
	position: relative;
	min-height: 520px;
}

.testimonial-card {
	position: absolute;
	width: min(340px, 52vw);
	min-height: 188px;
	padding: 27px 30px;
	border: 1px solid rgb(0 0 0 / 10%);
	border-radius: 8px;
	box-shadow: 0 18px 42px rgb(0 0 0 / 7%);
	animation: card-float 7s ease-in-out infinite;
	animation-delay: calc(var(--card-index) * -1.2s);
}

.testimonial-card:nth-child(1) {
	top: 10px;
	left: 10%;
}

.testimonial-card:nth-child(2) {
	top: 86px;
	right: 0;
}

.testimonial-card:nth-child(3) {
	top: 222px;
	left: 0;
}

.testimonial-card:nth-child(4) {
	right: 9%;
	bottom: 10px;
}

.tone-cream {
	background: #fff9dd;
}

.tone-mint {
	background: #e9fbff;
}

.tone-rose {
	background: #fff0eb;
}

.tone-white {
	background: white;
}

.stars {
	margin-bottom: 24px;
	font-size: 1.1rem;
	letter-spacing: 0.35em;
}

.testimonial-card h3 {
	margin-bottom: 16px;
	font-size: 1.55rem;
	line-height: 1.04;
}

.testimonial-card p {
	margin: 0;
	font-size: 1rem;
	line-height: 1.08;
}

.faq-section {
	padding: 76px clamp(24px, 7vw, 160px) 122px;
	background: var(--paper);
}

.faq-inner {
	width: min(100%, 1000px);
	margin: 0 auto;
}

.faq-inner h2 {
	margin: 0 0 30px;
	font-size: clamp(1.7rem, 2.7vw, 2.6rem);
	line-height: 1;
}

.faq-inner > p {
	max-width: 760px;
	margin: 0 0 44px;
	font-size: clamp(1.1rem, 1.7vw, 1.55rem);
	line-height: 1.13;
}

.faq-list {
	border-top: 1px solid #dedcd7;
}

.faq-item {
	border-bottom: 1px solid #dedcd7;
}

.faq-item button {
	display: flex;
	width: 100%;
	align-items: center;
	justify-content: space-between;
	min-height: 78px;
	cursor: pointer;
	padding: 0 28px 0 14px;
	color: #090909;
	background: transparent;
	font-size: clamp(1.05rem, 1.7vw, 1.44rem);
	text-align: left;
}

.faq-item button span:last-child {
	font-size: 1.8rem;
	transition: transform 200ms ease;
}

.faq-item.is-open button span:last-child {
	transform: rotate(180deg);
}

.faq-item p {
	max-width: 740px;
	margin: -6px 0 28px 14px;
	color: #4d4d4d;
	font-size: 1.05rem;
	line-height: 1.35;
}

.site-footer {
	padding: 0 clamp(24px, 5vw, 90px) 60px;
	background: var(--paper);
}

.social-links {
	justify-content: center;
	gap: 46px;
	padding-bottom: 66px;
}

.social-links a {
	display: grid;
	place-items: center;
	width: 44px;
	height: 44px;
	transition:
		opacity 180ms ease,
		transform 180ms ease;
}

.social-links img {
	display: block;
	width: 36px;
	max-height: 36px;
	object-fit: contain;
}

.social-links a:hover {
	opacity: 0.72;
	transform: translateY(-3px);
}

.footer-legal {
	justify-content: space-between;
	gap: 28px;
	padding-top: 42px;
	border-top: 1px solid #dedcd7;
	font-size: 1.1rem;
	font-weight: 900;
}

.footer-legal span {
	margin-left: auto;
}

.reveal {
	opacity: 0;
	transform: translateY(28px);
	transition:
		opacity 620ms ease,
		transform 760ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.reveal.is-revealed {
	opacity: 1;
	transform: none;
}

.landing-hero,
.product-card,
.product-card > img:not(.product-butterfly),
.service-grid article,
.growth-section h1,
.growth-section .shape,
.metric-card,
.metric-card img,
.partner-section h2,
.partner-marquee,
.proof-copy,
.testimonial-card,
.faq-item {
	will-change: transform, opacity, filter;
}

@keyframes menu-drop {
	from {
		opacity: 0;
		transform: translateY(-12px) scale(0.98);
	}

	to {
		opacity: 1;
		transform: translateY(0) scale(1);
	}
}

@keyframes content-pop {
	from {
		opacity: 0;
		transform: translateY(10px);
	}

	to {
		opacity: 1;
		transform: translateY(0);
	}
}

@keyframes float-slow {
	0%,
	100% {
		transform: translate3d(0, 0, 0) rotate(0deg);
	}

	50% {
		transform: translate3d(22px, -28px, 0) rotate(6deg);
	}
}

@keyframes card-float {
	0%,
	100% {
		transform: translateY(0);
	}

	50% {
		transform: translateY(-12px);
	}
}

@keyframes glass-sweep {
	0%,
	42% {
		opacity: 0;
		transform: translateX(-42%);
	}

	58% {
		opacity: 0.48;
	}

	100% {
		opacity: 0;
		transform: translateX(34%);
	}
}

@keyframes icon-glow {
	0%,
	100% {
		opacity: 0.2;
		transform: scale(0.78);
	}

	50% {
		opacity: 0.46;
		transform: scale(1);
	}
}

@keyframes butterfly-hover {
	0%,
	100% {
		transform: translate3d(0, 0, 0) rotate(-6deg);
	}

	50% {
		transform: translate3d(5px, -7px, 0) rotate(8deg);
	}
}

@keyframes icon-sun-orbit {
	0% {
		transform: translate3d(0, 0, 0) rotate(0deg) scale(1);
	}

	35% {
		transform: translate3d(0, -4px, 0) rotate(126deg) scale(1.04);
	}

	70% {
		transform: translate3d(0, 2px, 0) rotate(252deg) scale(0.98);
	}

	100% {
		transform: translate3d(0, 0, 0) rotate(360deg) scale(1);
	}
}

@keyframes icon-folder-float {
	0%,
	100% {
		transform: translate3d(0, 0, 0) rotate(0deg);
	}

	40% {
		transform: translate3d(0, -8px, 0) rotate(-2deg);
	}

	72% {
		transform: translate3d(0, -3px, 0) rotate(2deg);
	}
}

@keyframes icon-orbit-spin {
	0% {
		transform: rotate(-18deg) scale(1);
	}

	50% {
		transform: rotate(162deg) scale(1.035);
	}

	100% {
		transform: rotate(342deg) scale(1);
	}
}

@keyframes ripple-ring {
	0% {
		opacity: 0;
		transform: translate(-50%, -50%) scale(0.54);
	}

	22% {
		opacity: 0.9;
	}

	100% {
		opacity: 0;
		transform: translate(-50%, -50%) scale(1.34);
	}
}

@keyframes marquee {
	to {
		transform: translateX(-50%);
	}
}

@media (prefers-reduced-motion: reduce) {
	*,
	*::before,
	*::after {
		scroll-behavior: auto !important;
		animation-duration: 1ms !important;
		animation-iteration-count: 1 !important;
		transition-duration: 1ms !important;
	}
}

@media (max-width: 1180px) {
	.site-nav {
		grid-template-columns: 1fr auto;
	}

	.nav-links {
		display: none;
	}

	.cover-panel,
	.proof-section {
		grid-template-columns: 1fr;
	}

	.cover-dropdown {
		top: 118px;
	}

	.product-card-wide {
		flex-basis: clamp(420px, 46vw, 620px);
	}

	.metric-grid {
		grid-template-columns: repeat(2, minmax(0, 1fr));
	}

	.metric-card,
	.metric-orange,
	.metric-blue,
	.metric-gold,
	.metric-card:nth-child(5) {
		grid-column: span 1;
	}
}

@media (max-width: 760px) {
	.hero-section {
		--hero-gutter: 16px;
		padding: 20px 16px 58px;
	}

	.site-nav {
		position: relative;
		top: 0;
		grid-template-columns: minmax(0, 1fr) auto;
		gap: 12px;
		min-height: 0;
		padding: 4px 0;
	}

	.brand {
		grid-column: 1 / -1;
		min-width: 0;
	}

	.brand-mark {
		font-size: clamp(3rem, 16vw, 4.2rem);
	}

	.brand-text {
		font-size: clamp(0.82rem, 4vw, 1rem);
	}

	.nav-links {
		display: none;
	}

	.nav-actions {
		grid-column: 1 / -1;
		display: flex;
		justify-content: flex-start;
		gap: 10px;
		width: 100%;
	}

	.message-link {
		display: none;
	}

	.icon-button {
		display: none;
	}

	.primary-button {
		width: auto;
		min-width: 100px;
		min-height: 54px;
		padding: 0 12px;
		font-size: 0.95rem;
		line-height: 1.05;
		text-align: center;
		white-space: normal;
	}

	.cover-panel {
		grid-template-columns: 1fr;
		padding: 20px;
	}

	.cover-dropdown {
		position: static;
		z-index: auto;
		top: auto;
		right: auto;
		left: auto;
		margin-top: 12px;
		animation: none;
		transform: none;
	}

	.cover-feature {
		justify-self: stretch;
		width: 100%;
		height: 300px;
	}

	.landing-hero {
		min-height: 0;
		padding-top: 64px;
	}

	.hero-pill {
		min-height: 48px;
		margin-bottom: 30px;
		padding: 0 22px;
		font-size: 1rem;
	}

	.landing-hero h1 {
		max-width: 10ch;
		font-size: clamp(1.75rem, 8.8vw, 2.9rem);
	}

	.landing-hero > p:last-child {
		max-width: 18ch;
		font-size: clamp(1rem, 5.1vw, 1.32rem);
		line-height: 1.14;
	}

	.cover-list,
	.service-grid,
	.metric-grid {
		grid-template-columns: 1fr;
	}

	.cover-item {
		grid-template-columns: 42px 1fr;
	}

	.cover-feature {
		min-height: 290px;
	}

	.product-card {
		flex-basis: min(74vw, 300px);
		height: 360px;
		min-height: 0;
	}

	.product-card-wide {
		flex-basis: min(82vw, 370px);
	}

	.social-links {
		gap: 26px;
		padding-bottom: 46px;
	}

	.social-links a {
		width: 34px;
		height: 34px;
	}

	.social-links img {
		width: 30px;
		max-height: 30px;
	}

	.service-band h2 {
		max-width: 100%;
	}

	.service-grid article,
	.service-grid article:first-child {
		min-height: 0;
		padding: 0 0 26px;
		border-left: 0;
		border-bottom: 1px solid rgb(251 131 82 / 22%);
	}

	.growth-section h1 {
		font-size: clamp(3.6rem, 17vw, 5.8rem);
	}

	.metric-card > div,
	.metric-gold > div {
		width: 100%;
	}

	.metric-gold img {
		opacity: 0.25;
	}

	.partner-section,
	.proof-section,
	.faq-section {
		padding-right: 18px;
		padding-left: 18px;
	}

	.testimonial-cloud {
		display: grid;
		gap: 16px;
		min-height: 0;
	}

	.testimonial-card,
	.testimonial-card:nth-child(n) {
		position: static;
		width: 100%;
	}

	.footer-legal {
		flex-direction: column;
		align-items: flex-start;
	}

	.footer-legal span {
		margin-left: 0;
	}

	.floating-section-nav {
		display: none;
	}
}

.scroll-progress {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	height: 5px;
	background: var(--aqua);
	transform-origin: 0;
	transform: scaleX(0);
	z-index: 999;
	transition: transform 100ms linear;
}
